import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test(
    "a vendor cannot be renamed to another vendor's name, whatever the case",
    { tag: "@LIF-10" },
    async ({ apiAs }) => {
      // Arrange: a unique suffix keeps names distinct from other parallel tests.
      const member = await apiAs("member");
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      const atlasName = `Atlas Freight ${suffix}`;
      const borealisName = `Borealis Freight ${suffix}`;

      const atlas = await expectStatus<{ id: string; name: string }>(
        await member.post("/api/vendors", {
          data: { name: atlasName, category: "logistics", contact_email: `ops-atlas-${suffix}@example.test` },
        }),
        201,
      );
      const borealis = await expectStatus<{ id: string; name: string }>(
        await member.post("/api/vendors", {
          data: { name: borealisName, category: "logistics", contact_email: `ops-borealis-${suffix}@example.test` },
        }),
        201,
      );
      expect(atlas.name).toBe(atlasName);
      expect(borealis.name).toBe(borealisName);

      // Act: rename Borealis to Atlas's name with different casing.
      const renameTo = atlasName.toUpperCase();
      const response = await member.patch(`/api/vendors/${borealis.id}`, {
        data: { name: renameTo },
      });

      // Assert: the rename is rejected with a conflict.
      const body = await expectStatus<{ error: { code: string } }>(response, 409);
      expect(body.error.code).toBe("vendor_name_taken");

      // Assert: Borealis keeps its original name.
      const current = await expectStatus<{ id: string; name: string }>(
        await member.get(`/api/vendors/${borealis.id}`),
        200,
      );
      expect(current.name).toBe(borealisName);
    },
  );
});
